data: {"index":1,"delta":{"text":" assembly, which had not met since 1614, became the catalyst for the revolution when the Third Estate broke","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" away to form the National Assembly, signaling the end of absolute royal authority.\n\n### The Consequences: A New World Order\n\nThe revolution did","type":"text"},"event_type":"step.delta"}

event: step.delta
data: {"index":1,"delta":{"text":" not end with the fall of the Bastille; it evolved through phases of constitutional monarchy, radical republicanism, and eventually the rise","type":"text"},"event_type":"step.delta"}

